const upsertAlert = `-- name: UpsertAlert :one
INSERT INTO alerts (rule, severity, subject_user_id, approver_ids, involved_ids, subject, num_params, text_params,
                    business_date, first_at, last_at, shift_id, invoice_id, audit_ids, group_key, dedup_key)
VALUES ($1, $2, $3::uuid, $4::uuid[], $5::uuid[], $6,
        $7, $8, $9, $10, $10, $11::uuid, $12::uuid,
        ARRAY[$13::bigint], $14, $15::text)
ON CONFLICT (rule, group_key) WHERE status = 'OPEN' DO UPDATE SET
    count = alerts.count + 1,
    last_at = EXCLUDED.last_at,
    num_params = EXCLUDED.num_params,
    text_params = EXCLUDED.text_params,
    subject = CASE WHEN (', ' || alerts.subject || ', ') LIKE ('%, ' || EXCLUDED.subject || ', %') THEN alerts.subject
                   ELSE alerts.subject || ', ' || EXCLUDED.subject END,
    approver_ids = ARRAY(SELECT DISTINCT x FROM unnest(alerts.approver_ids || EXCLUDED.approver_ids) AS x),
    involved_ids = ARRAY(SELECT DISTINCT x FROM unnest(alerts.involved_ids || EXCLUDED.involved_ids) AS x),
    audit_ids = alerts.audit_ids || EXCLUDED.audit_ids,
    version = alerts.version + 1
RETURNING id, seq, rule, severity, status, subject_user_id, approver_ids, involved_ids, subject, num_params, text_params, count, business_date, first_at, last_at, shift_id, invoice_id, audit_ids, group_key, dedup_key, resolved_by_user_id, resolved_at, note, version
`

type UpsertAlertParams struct {
	Rule          string      `json:"rule"`
	Severity      string      `json:"severity"`
	SubjectUserID pgtype.UUID `json:"subject_user_id"`
	ApproverIds   []uuid.UUID `json:"approver_ids"`
	InvolvedIds   []uuid.UUID `json:"involved_ids"`
	Subject       string      `json:"subject"`
	NumParams     []byte      `json:"num_params"`
	TextParams    []byte      `json:"text_params"`
	BusinessDate  pgtype.Date `json:"business_date"`
	At            time.Time   `json:"at"`
	ShiftID       pgtype.UUID `json:"shift_id"`
	InvoiceID     pgtype.UUID `json:"invoice_id"`
	AuditID       int64       `json:"audit_id"`
	GroupKey      string      `json:"group_key"`
	DedupKey      pgtype.Text `json:"dedup_key"`
}

// A new alert, or a repeat firing grouped into the open alert of the same rule +
// group (count + 1, params replaced, subject/approvers/involved/audit ids added).
// count = 1 in the result means it was created.
func (q *Queries) UpsertAlert(ctx context.Context, arg UpsertAlertParams) (Alert, error) {
	row := q.db.QueryRow(ctx, upsertAlert,
		arg.Rule,
		arg.Severity,
		arg.SubjectUserID,
		arg.ApproverIds,
		arg.InvolvedIds,
		arg.Subject,
		arg.NumParams,
		arg.TextParams,
		arg.BusinessDate,
		arg.At,
		arg.ShiftID,
		arg.InvoiceID,
		arg.AuditID,
		arg.GroupKey,
		arg.DedupKey,
	)
	var i Alert
	err := row.Scan(
		&i.ID,
		&i.Seq,
		&i.Rule,
		&i.Severity,
		&i.Status,
		&i.SubjectUserID,
		&i.ApproverIds,
		&i.InvolvedIds,
		&i.Subject,
		&i.NumParams,
		&i.TextParams,
		&i.Count,
		&i.BusinessDate,
		&i.FirstAt,
		&i.LastAt,
		&i.ShiftID,
		&i.InvoiceID,
		&i.AuditIds,
		&i.GroupKey,
		&i.DedupKey,
		&i.ResolvedByUserID,
		&i.ResolvedAt,
		&i.Note,
		&i.Version,
	)
	return i, err
}
